:root {
  --bg: #eef2f7;
  --surface: #ffffff;
  --surface-muted: #f6f8fb;
  --surface-tint: #f1f4f8;
  --border: rgba(148, 163, 184, 0.12);
  --border-strong: rgba(100, 116, 139, 0.24);
  --text: #111827;
  --muted: #667085;
  --primary: #1f2937;
  --primary-strong: #111827;
  --primary-soft: #e5e7eb;
  --accent: #334155;
  --accent-soft: #eef2f7;
  --danger: #b91c1c;
  --success: #334155;
  --panel: rgba(255, 255, 255, 0.94);
  --line: #d5dfec;
  --shadow-sm: 0 8px 20px rgba(15, 23, 42, 0.05);
  --shadow-md: 0 24px 60px rgba(15, 23, 42, 0.08);
}

.mini-horizon-instance-domains {
  display: grid;
  grid-column: 1 / -1;
  gap: 7px;
  padding: 9px 10px;
  border: 1px solid #dbeafe;
  border-radius: 8px;
  background: #f8fbff;
}

.mini-horizon-instance-domains > span:first-child {
  color: #1d4ed8;
  font-size: 12px;
  font-weight: 800;
}

.mini-horizon-instance-domains > div,
.mini-horizon-inline-form {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.mini-horizon-instance-domains a {
  color: inherit;
  text-decoration: none;
}

.mini-horizon-inline-form input,
.mini-horizon-inline-form select {
  width: auto;
  min-height: 34px;
}

.mini-horizon-inline-form input:first-child {
  min-width: 190px;
}

.mini-horizon-inline-form > span {
  color: #64748b;
  font-size: 12px;
}

* { box-sizing: border-box; }
html, body, #root { min-height: 100%; }
body {
  margin: 0;
  background:
    radial-gradient(circle at top left, rgba(148, 163, 184, 0.12), transparent 28%),
    radial-gradient(circle at top right, rgba(203, 213, 225, 0.16), transparent 24%),
    linear-gradient(180deg, #f8fafc 0%, var(--bg) 42%, #e8edf4 100%);
  color: var(--text);
  font-family: "Pretendard Variable", "Pretendard", "Segoe UI", Arial, sans-serif;
  font-size: 14px;
  line-height: 1.5;
}

button, input, textarea, select { font: inherit; }

.shell { min-height: 100vh; padding: 20px 16px 16px; background: transparent; }
.skip-link {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 80;
  transform: translateY(-160%);
  padding: 10px 12px;
  border: 1px solid #111827;
  border-radius: 8px;
  background: #111827;
  color: #fff;
  font-weight: 800;
  text-decoration: none;
}
.skip-link:focus-visible {
  transform: translateY(0);
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.auth-shell, .app-shell, .loading-shell, .admin-page, .admin-login-wrap { max-width: 1280px; margin: 0 auto; }
.loading-shell { display: grid; place-items: center; min-height: calc(100vh - 32px); }
.view-loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  pointer-events: none;
}
.loading-card, .admin-simple-card {
  background: var(--surface);
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 16px;
  box-shadow: 0 18px 36px rgba(15, 23, 42, 0.06);
}
.loading-preview-shell {
  padding: 24px;
}
.loading-preview-grid {
  display: grid;
  gap: 18px;
  width: min(1120px, 100%);
}
.loading-preview-grid.has-pair {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.loading-preview-item {
  display: grid;
  gap: 10px;
  justify-items: center;
  min-width: 0;
}
.loading-preview-item > .card-label {
  justify-self: start;
}
.portal-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1100;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(15, 23, 42, 0.42);
  backdrop-filter: blur(8px);
}
.portal-modal-card {
  width: min(720px, calc(100vw - 32px));
  max-height: calc(100dvh - 48px);
  overflow: auto;
  padding: 28px;
  border: 1px solid rgba(226, 232, 240, 0.96);
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 28px 80px rgba(15, 23, 42, 0.24);
}
.session-loading-card {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 14px;
  align-items: center;
  width: min(520px, calc(100vw - 48px));
  padding: 18px;
  overflow: hidden;
  border-color: rgba(37, 99, 235, 0.18);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(248, 250, 252, 0.98) 100%),
    repeating-linear-gradient(90deg, rgba(37, 99, 235, 0.06) 0 1px, transparent 1px 26px);
}
.session-loading-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(59, 130, 246, 0.12) 48%, transparent 100%);
  transform: translateX(-100%);
  animation: session-loading-scan 2.4s ease-in-out infinite;
  pointer-events: none;
}
.session-loading-signal {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
  width: 52px;
  height: 52px;
  padding: 10px;
  border: 1px solid #dbeafe;
  border-radius: 8px;
  background: #eff6ff;
}
.session-loading-signal span {
  width: 7px;
  min-height: 12px;
  border-radius: 999px;
  background: #2563eb;
  animation: session-loading-signal-pulse 1.05s ease-in-out infinite;
}
.session-loading-signal span:nth-child(2) {
  min-height: 22px;
  animation-delay: 0.12s;
}
.session-loading-signal span:nth-child(3) {
  min-height: 32px;
  animation-delay: 0.24s;
}
.session-loading-terminal {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 10px;
  min-width: 0;
}
.session-loading-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: #475569;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.session-loading-head > span:nth-child(2) {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.session-loading-head i {
  margin-left: auto;
  padding: 3px 7px;
  border-radius: 999px;
  background: #dcfce7;
  color: #166534;
  font-style: normal;
  line-height: 1;
}
.session-loading-emote {
  display: inline-grid;
  place-items: center;
  min-width: 32px;
  height: 24px;
  padding: 0 7px;
  border: 1px solid #bfdbfe;
  border-radius: 6px;
  background: #ffffff;
  color: #1d4ed8;
  font-family: "JetBrains Mono", "D2Coding", "Pretendard Variable", monospace;
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
}
.session-loading-copy {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  gap: 6px;
  color: var(--primary);
  font-family: "JetBrains Mono", "D2Coding", "Pretendard Variable", monospace;
  font-size: 14px;
  font-weight: 900;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.session-loading-prefix {
  color: var(--muted);
}
.session-loading-cursor {
  color: var(--accent);
  animation: session-loading-cursor-blink 1s steps(2, start) infinite;
}
.session-loading-rail {
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: #e2e8f0;
}
.session-loading-rail span {
  display: block;
  width: 42%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2563eb 0%, #14b8a6 100%);
  animation: session-loading-rail-slide 1.45s ease-in-out infinite;
}
.session-loading-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}
.session-loading-steps span {
  min-width: 0;
  overflow: hidden;
  padding: 6px 7px;
  border: 1px solid #e2e8f0;
  border-radius: 7px;
  background: #ffffff;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.session-loading-steps span.is-active {
  border-color: #93c5fd;
  background: #eff6ff;
  color: #1d4ed8;
}

.exam-preparation-dialog {
  width: min(620px, calc(100vw - 32px));
}
.exam-preparation-dialog .session-loading-terminal {
  gap: 12px;
}
.exam-preparation-dialog h3 {
  margin: 3px 0 0;
}
.exam-preparation-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 16px;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
}
.exam-preparation-meta strong {
  color: #1d4ed8;
}
.exam-preparation-detail {
  margin: 0;
  padding: 8px 10px;
  border-radius: 7px;
  background: #f8fafc;
}

.ai-lab-view {
  --ai-lab-accent: #7c3aed;
}
.ai-lab-hero {
  background:
    linear-gradient(135deg, rgba(245, 243, 255, 0.94), rgba(239, 246, 255, 0.96)),
    #ffffff;
}
.ai-lab-backend-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}
.ai-lab-backend-card {
  display: grid;
  gap: 7px;
  min-width: 0;
  padding: 18px;
  border: 1px solid #dbe5f2;
  border-radius: 10px;
  background: #ffffff;
  color: #0f172a;
  text-align: left;
  cursor: pointer;
}
.ai-lab-backend-card:hover:not(:disabled) {
  border-color: #a78bfa;
  background: #faf5ff;
}
.ai-lab-backend-card.is-selected {
  border-color: var(--ai-lab-accent);
  background: #f5f3ff;
  box-shadow: inset 0 0 0 1px var(--ai-lab-accent);
}
.ai-lab-backend-card:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.ai-lab-backend-card > span {
  color: var(--ai-lab-accent);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}
.ai-lab-backend-card > strong {
  font-size: 17px;
}
.ai-lab-backend-card > small {
  color: #64748b;
  line-height: 1.55;
}
.ai-lab-resource-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}
.ai-lab-resource-grid .admin-summary-card small {
  overflow-wrap: anywhere;
}
.ai-lab-console-panel {
  display: grid;
  gap: 12px;
  scroll-margin-top: 24px;
}
.ai-lab-console-panel > .hint {
  margin: -6px 0 0;
}
.ai-lab-console-panel .terminal-root {
  box-sizing: border-box;
  width: 100%;
  height: clamp(360px, 55vh, 560px);
  min-height: 0;
  max-height: 560px;
  overflow: hidden;
  padding: 12px;
  border: 1px solid #1e293b;
  border-radius: 10px;
  background: #07111f;
}
.ai-lab-console-panel .terminal-root .xterm {
  height: 100%;
  min-height: 0;
}
.ai-lab-console-panel .terminal-root .xterm-viewport {
  height: 100% !important;
  min-height: 0;
}
.ai-lab-console-panel .terminal-root .xterm-screen {
  min-height: 0;
}
.ai-vm-profile-list {
  display: grid;
  gap: 12px;
}
.ai-vm-profile-card {
  display: grid;
  gap: 14px;
}
.ai-vm-profile-card select[multiple] {
  min-height: 108px;
}
.ai-vm-profile-card .admin-field-wide {
  grid-column: 1 / -1;
}

@media (max-width: 720px) {
  .ai-lab-backend-grid {
    grid-template-columns: 1fr;
  }
  .ai-lab-console-panel .terminal-root {
    height: 380px;
  }
}

@keyframes session-loading-cursor-blink {
  0%, 48% { opacity: 1; }
  49%, 100% { opacity: 0; }
}

@keyframes session-loading-scan {
  0% { transform: translateX(-120%); }
  48%, 100% { transform: translateX(120%); }
}

@keyframes session-loading-signal-pulse {
  0%, 100% { transform: scaleY(0.72); opacity: 0.62; }
  42% { transform: scaleY(1); opacity: 1; }
}

@keyframes session-loading-rail-slide {
  0% { transform: translateX(-110%); }
  54% { transform: translateX(70%); }
  100% { transform: translateX(180%); }
}

@keyframes terminal-console-loader-pulse {
  0%, 100% { transform: scaleY(0.72); opacity: 0.62; }
  42% { transform: scaleY(1); opacity: 1; }
}

@keyframes terminal-readiness-icon-bob {
  0%, 100% { transform: translateY(0) scale(1); }
  44% { transform: translateY(-2px) scale(1.06); }
}

@keyframes terminal-readiness-flow {
  0%, 100% { opacity: 0.42; transform: translateX(-6px) scale(0.94); }
  35%, 55% { opacity: 1; transform: translateX(0) scale(1.08); }
}

@keyframes terminal-readiness-rail {
  0% { transform: translateX(-120%); opacity: 0; }
  18%, 70% { opacity: 1; }
  100% { transform: translateX(120%); opacity: 0; }
}

@media (max-width: 520px) {
  .session-loading-card {
    grid-template-columns: 1fr;
    width: min(420px, calc(100vw - 32px));
    padding: 16px;
  }
  .session-loading-signal {
    justify-self: start;
    width: 46px;
    height: 44px;
    padding: 8px;
  }
  .session-loading-copy {
    font-size: 13px;
  }
  .session-loading-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 920px) {
  .loading-preview-grid.has-pair {
    grid-template-columns: 1fr;
  }
}

.auth-shell {
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) 420px;
  gap: 20px;
  align-items: start;
}
.auth-hero, .auth-panel, .sidebar, .workspace {
  background: var(--surface);
  border: 1px solid transparent;
  border-radius: 24px;
  box-shadow: var(--shadow-sm);
}

.auth-hero {
  position: relative;
  overflow: hidden;
  padding: 28px;
  background:
    radial-gradient(circle at top left, rgba(148, 163, 184, 0.1), transparent 24%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.99) 0%, rgba(247, 250, 253, 0.98) 100%);
  border-color: rgba(226, 232, 240, 0.92);
  border-radius: 20px;
  box-shadow: 0 20px 52px rgba(11, 18, 32, 0.06);
}
.compact-hero { display: grid; gap: 18px; }
.auth-panel, .workspace { padding: 22px; }
.auth-panel {
  align-self: start;
  position: sticky;
  top: 20px;
  min-width: 0;
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.99) 0%, rgba(246, 248, 251, 0.98) 100%);
  border: 1px solid rgba(226, 232, 240, 0.9);
  box-shadow: 0 24px 60px rgba(11, 18, 32, 0.08);
}
.sidebar {
  padding: 18px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(245, 247, 250, 0.95) 100%),
    var(--surface);
  color: var(--text);
  border-color: rgba(159, 178, 205, 0.65);
}

.eyebrow, .card-label {
  margin: 0 0 10px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.auth-hero h1, .workspace-header h2, .course-detail h3, .terminal-toolbar h3 {
  margin: 0;
  font-size: 24px;
  line-height: 1.14;
  letter-spacing: -0.03em;
}

.hero-copy, .hero-card p, .course-list-item p, .course-detail-copy, .terminal-note, .hint, .summary-item span {
  color: var(--muted);
}
.landing-intro {
  display: grid;
  gap: 12px;
  width: 100%;
  max-width: 100%;
}
.landing-hero-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}
.landing-intro .eyebrow {
  margin-bottom: 0;
}
.landing-brand-lockup {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  width: fit-content;
  max-width: 100%;
}
.landing-brand-mark {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  width: 42px;
  height: 42px;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 11px;
  background: #0f172a;
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.12);
}
.landing-brand-mark img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.landing-brand-terminal-glyph {
  color: #dcfce7;
  font-family: "JetBrains Mono", "D2Coding", Consolas, monospace;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: 0;
  line-height: 1;
}
.landing-brand-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.landing-brand-copy strong {
  color: #0f172a;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.06em;
  line-height: 1.2;
}
.landing-brand-copy small {
  color: #475569;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}
.landing-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  padding-top: 6px;
}
.landing-hero-primary,
.landing-hero-secondary,
.landing-hero-tertiary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 50px;
  padding: 0 18px;
  border: 1px solid rgba(15, 23, 42, 0.28);
  border-radius: 10px;
  font-size: 16px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
  cursor: pointer;
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease, background 160ms ease, color 160ms ease;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.1);
  text-decoration: none;
}
.landing-hero-primary {
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  color: #f8fafc;
}
.landing-hero-secondary {
  background: rgba(255, 255, 255, 0.82);
  color: #0f172a;
  backdrop-filter: blur(10px);
}
.landing-hero-tertiary {
  border-color: rgba(148, 163, 184, 0.42);
  background: rgba(255, 255, 255, 0.54);
  color: #334155;
  box-shadow: none;
}
.landing-hero-primary:hover,
.landing-hero-secondary:hover,
.landing-hero-tertiary:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 30px rgba(15, 23, 42, 0.14);
}
.landing-hero-primary:hover {
  border-color: rgba(15, 23, 42, 0.4);
}
.landing-hero-secondary:hover {
  background: rgba(255, 255, 255, 0.94);
  border-color: rgba(15, 23, 42, 0.34);
}
.landing-hero-tertiary:hover {
  background: rgba(255, 255, 255, 0.88);
  border-color: rgba(100, 116, 139, 0.48);
}
.landing-hero-primary:focus-visible,
.landing-hero-secondary:focus-visible,
.landing-hero-tertiary:focus-visible {
  outline: 2px solid rgba(59, 130, 246, 0.65);
  outline-offset: 2px;
}
.landing-hero-proof {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.landing-hero-proof-chip {
  display: inline-flex;
  align-items: center;
  padding: 7px 12px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  color: #1f2937;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.5;
  backdrop-filter: blur(14px);
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.04);
}
.landing-customer-logos {
  display: grid;
  gap: 8px;
  padding: 4px 0 2px;
}
.landing-customer-logos > span {
  color: #475569;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
.landing-customer-logo-rail {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}
.landing-customer-logo-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 112px;
  height: 42px;
  padding: 8px 12px;
  border: 1px solid rgba(203, 213, 225, 0.88);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.04);
  filter: grayscale(0.35);
  opacity: 0.9;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, filter 0.16s ease, opacity 0.16s ease, transform 0.16s ease;
}
.landing-customer-logo-link:hover {
  border-color: rgba(37, 99, 235, 0.32);
  box-shadow: 0 12px 24px rgba(37, 99, 235, 0.08);
  filter: none;
  opacity: 1;
  transform: translateY(-1px);
}
.landing-customer-logo-link img {
  display: block;
  max-width: 100%;
  max-height: 24px;
  object-fit: contain;
}
.landing-metrics-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 10px;
}
.landing-metric-card {
  display: grid;
  gap: 5px;
  padding: 13px 14px;
  border: 1px solid rgba(226, 232, 240, 0.9);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 20px rgba(11, 18, 32, 0.045);
}
.landing-metric-card span {
  color: #475569;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.landing-metric-card strong {
  color: #081120;
  font-size: 24px;
  line-height: 1;
  letter-spacing: -0.04em;
}
.landing-metric-card small {
  color: #475569;
  font-size: 12px;
  line-height: 1.5;
}
.hero-version,
.workspace-version,
.brand-version {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.brand-version {
  display: block;
}
.landing-course-ticker-panel {
  display: grid;
  gap: 10px;
  padding: 14px 16px;
  border: 1px solid rgba(226, 232, 240, 0.92);
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 12px 26px rgba(11, 18, 32, 0.035);
}
.landing-course-ticker {
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.landing-course-ticker-track {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  width: auto;
  padding: 0;
  animation: none;
}
.landing-course-ticker:hover .landing-course-ticker-track {
  animation-play-state: paused;
}
.landing-course-ticker-chip {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0 12px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 999px;
  background: #ffffff;
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.landing-course-ticker-chip.is-government {
  border-color: rgba(147, 197, 253, 0.92);
  background: linear-gradient(135deg, rgba(248, 251, 255, 0.98) 0%, rgba(219, 234, 254, 0.98) 100%);
  color: #1d4ed8;
}
.landing-hero-schedule {
  display: grid;
  gap: 12px;
  max-width: 100%;
  padding: 16px;
  border: 1px solid rgba(191, 219, 254, 0.72);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 16px 30px rgba(15, 23, 42, 0.08);
}
.landing-hero-schedule.is-simple {
  width: 100%;
  max-width: min(720px, 100%);
  padding: 14px;
  gap: 10px;
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.06);
}
.landing-hero-schedule-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.landing-hero-schedule-head > div {
  min-width: 0;
}
.landing-hero-schedule-head span {
  color: #2563eb;
  font-size: 12px;
  font-weight: 800;
}
.landing-hero-schedule-head strong {
  display: block;
  color: #0f172a;
  font-size: 16px;
  overflow-wrap: anywhere;
}
.landing-hero-schedule-head small {
  flex: 0 0 auto;
  padding: 5px 9px;
  border: 1px solid rgba(191, 219, 254, 0.9);
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  font-size: 11px;
  font-weight: 800;
}
.landing-hero-schedule-empty {
  display: grid;
  gap: 7px;
  min-height: 128px;
  align-content: center;
  justify-items: start;
  padding: 14px;
  border: 1px dashed rgba(148, 163, 184, 0.7);
  border-radius: 12px;
  background: rgba(248, 250, 252, 0.82);
}
.landing-hero-schedule-empty strong {
  color: #0f172a;
  font-size: 13px;
}
.landing-hero-schedule-empty span {
  color: #64748b;
  font-size: 11px;
  line-height: 1.45;
}
.landing-hero-schedule-empty .mini-btn {
  min-height: 28px;
  margin-top: 2px;
  border-radius: 8px;
}
.landing-hero-schedule-empty .mini-btn:disabled {
  opacity: 0.48;
  cursor: default;
}
.landing-simple-schedule-list {
  display: grid;
  gap: 8px;
}
.landing-simple-schedule-item {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid rgba(219, 234, 254, 0.92);
  border-radius: 10px;
  background: rgba(248, 250, 252, 0.92);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease, transform 0.16s ease;
}
.landing-simple-schedule-item:hover,
.landing-simple-schedule-item:focus-visible {
  border-color: rgba(37, 99, 235, 0.52);
  background: #ffffff;
  transform: translateY(-1px);
}
.landing-simple-schedule-item span {
  color: #2563eb;
  font-size: 11px;
  font-weight: 800;
  overflow-wrap: anywhere;
}
.landing-simple-schedule-item strong {
  color: #0f172a;
  font-size: 13px;
  line-height: 1.35;
  overflow-wrap: anywhere;
  word-break: keep-all;
}
.landing-simple-schedule-item small {
  color: #64748b;
  font-size: 11px;
  line-height: 1.35;
  overflow-wrap: anywhere;
  word-break: keep-all;
}
.landing-schedule-detail-modal {
  width: min(680px, calc(100vw - 32px));
  max-height: calc(100dvh - 48px);
  padding: 28px;
  gap: 18px;
  overflow: auto;
}
.landing-schedule-detail-modal .portal-detail-head {
  align-items: flex-start;
  margin-bottom: 6px;
}
.landing-schedule-detail-modal .portal-detail-head h3 {
  margin: 4px 0 0;
  font-size: 21px;
  line-height: 1.25;
}
.landing-schedule-detail-modal .portal-detail-head .mini-btn {
  margin-top: -4px;
}
.landing-schedule-detail-modal .portal-chip-row {
  margin-top: 2px;
}
.landing-schedule-detail-modal .schedule-detail-grid {
  padding: 18px;
  gap: 11px 16px;
}
.landing-schedule-detail-modal .admin-inline-actions {
  gap: 10px;
  padding-top: 2px;
}
.landing-schedule-modal-backdrop {
  z-index: 1200;
  background: rgba(15, 23, 42, 0.44);
}
.landing-schedule-modal-backdrop .card-label {
  margin-bottom: 8px;
}
.landing-schedule-modal-backdrop .portal-modal-card {
  box-shadow: 0 28px 80px rgba(15, 23, 42, 0.24);
}
.landing-quote-modal-backdrop {
  align-items: flex-start;
  overflow: auto;
  padding: 32px 16px;
}
.landing-quote-modal {
  width: min(760px, calc(100vw - 32px));
}
.landing-quote-form {
  display: grid;
  gap: 14px;
}
.landing-quote-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.landing-quote-consent {
  align-items: flex-start;
  border: 1px solid rgba(34, 197, 94, 0.28);
  border-radius: 10px;
  background: #f0fdf4;
  padding: 12px;
}
.landing-quote-honeypot {
  position: absolute;
  left: -10000px;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
@media (max-width: 720px) {
  .landing-quote-grid {
    grid-template-columns: 1fr;
  }
  .landing-quote-modal {
    width: min(100%, calc(100vw - 24px));
    padding: 18px;
  }
}
.landing-demo-panel {
  display: grid;
  gap: 12px;
  padding: 18px;
  border: 1px solid rgba(226, 232, 240, 0.92);
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(11, 18, 32, 0.035);
}
.landing-demo-panel.is-compact {
  grid-template-columns: minmax(180px, 0.42fr) minmax(0, 1fr);
  align-items: center;
  padding: 18px;
}
.landing-demo-head {
  display: grid;
  gap: 4px;
}
.landing-demo-head strong {
  color: var(--text);
  font-size: 16px;
}
.landing-demo-head span {
  color: #475569;
  font-size: 13px;
  line-height: 1.6;
}
.landing-demo-frame {
  width: min(100%, 920px);
  margin: 0 auto;
  overflow: hidden;
  border: 1px solid rgba(29, 78, 216, 0.16);
  border-radius: 14px;
  background: #0f172a;
  box-shadow: 0 20px 40px rgba(15, 23, 42, 0.14);
  aspect-ratio: 16 / 9;
}
.landing-demo-video {
  display: block;
  width: 100%;
  min-height: clamp(180px, 18vw, 280px);
  height: 100%;
  border: 0;
  background: #0f172a;
  object-fit: cover;
}
.file-upload-btn {
  position: relative;
  overflow: hidden;
  cursor: pointer;
}
.file-upload-btn input[type="file"] {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}
.landing-admin-preview {
  margin-top: 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  background: #0f172a;
}
.landing-admin-preview-media {
  display: block;
  width: 100%;
  min-height: 240px;
  height: 320px;
  border: 0;
  background: #0f172a;
  object-fit: cover;
}
.landing-brand-preview {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  min-height: 96px;
  margin-top: 12px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: #fff;
}
.landing-brand-preview-logo {
  width: 180px;
  max-width: 100%;
  height: auto;
  object-fit: contain;
}
.landing-brand-preview-favicon {
  width: 48px;
  height: 48px;
  object-fit: contain;
}
.landing-customer-logo-editor {
  display: grid;
  gap: 12px;
}
.landing-customer-logo-admin-list {
  display: grid;
  gap: 10px;
}
.landing-customer-logo-admin-row {
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: #fff;
}
.landing-customer-logo-admin-preview {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 96px;
  height: 54px;
  padding: 8px;
  border: 1px solid rgba(203, 213, 225, 0.82);
  border-radius: 10px;
  background: #f8fafc;
  color: #2563eb;
  font-size: 12px;
  font-weight: 800;
}
.landing-customer-logo-admin-preview img {
  display: block;
  max-width: 100%;
  max-height: 34px;
  object-fit: contain;
}
.landing-customer-logo-admin-fields {
  display: grid;
  grid-template-columns: minmax(140px, 0.72fr) minmax(180px, 1fr) minmax(180px, 0.9fr);
  gap: 10px;
}
.landing-customer-logo-admin-fields label {
  display: grid;
  gap: 5px;
  min-width: 0;
}
.landing-customer-logo-admin-fields span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}
.landing-customer-logo-admin-actions {
  display: grid;
  gap: 8px;
  justify-items: end;
}
.landing-customer-logo-admin-actions .toggle-row {
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text);
}
.landing-customer-logo-admin-empty {
  padding: 14px;
  border: 1px dashed rgba(148, 163, 184, 0.72);
  border-radius: 12px;
  color: var(--muted);
  background: #f8fafc;
  font-size: 13px;
}
.compact-status-list {
  gap: 4px;
  margin-top: 10px;
}
@media (max-width: 920px) {
  .landing-customer-logo-admin-row,
  .landing-customer-logo-admin-fields {
    grid-template-columns: 1fr;
  }
  .landing-customer-logo-admin-actions {
    justify-items: start;
  }
}
.landing-curriculum-panel {
  display: grid;
  gap: 12px;
  padding: 18px;
  border: 1px solid rgba(226, 232, 240, 0.92);
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(11, 18, 32, 0.035);
}
.landing-accordion-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.landing-accordion-head > div {
  display: grid;
  gap: 4px;
}
.landing-accordion-toggle {
  flex: 0 0 auto;
  padding: 10px 14px;
  border: 1px solid rgba(203, 213, 225, 0.9);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.96);
  color: var(--text);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}
.landing-curriculum-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}
.landing-curriculum-filter {
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid rgba(148, 163, 184, 0.42);
  border-radius: 8px;
  background: #ffffff;
  color: var(--text);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}
.landing-curriculum-filter.is-active {
  border-color: rgba(15, 23, 42, 0.92);
  background: #111827;
  color: #ffffff;
}
.landing-curriculum-filter.is-government {
  border-color: rgba(147, 197, 253, 0.88);
  color: #1d4ed8;
}
.landing-curriculum-filter.is-government.is-active {
  border-color: rgba(37, 99, 235, 0.72);
  background: #2563eb;
  color: #ffffff;
}
.landing-curriculum-accordion {
  display: grid;
  transition: grid-template-rows 180ms ease, opacity 180ms ease;
}
.landing-curriculum-accordion.is-expanded {
  grid-template-rows: 1fr;
  opacity: 1;
}
.landing-curriculum-accordion.is-collapsed {
  grid-template-rows: 0fr;
  opacity: 0.92;
}
.landing-curriculum-accordion > .landing-curriculum-grid {
  overflow: hidden;
  min-height: 0;
}
.landing-v2-shell {
  align-items: start;
}
.landing-v2-metrics {
  margin-top: 2px;
}
.landing-v2-metrics .landing-metric-card {
  min-height: 92px;
  border-radius: 10px;
}
.landing-v2-metrics .landing-metric-card strong {
  font-size: 23px;
}
.landing-guest-preview-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.course-preview-toggle-row {
  display: flex;
  align-items: flex-start;
  justify-content: flex-start;
  margin-top: 2px;
}
.course-preview-toggle {
  max-width: 100%;
  white-space: normal;
  border-radius: 14px;
  padding: 10px 14px;
}
.course-preview-toggle.is-disabled {
  opacity: 0.7;
  background: #f8fafc;
}
.auth-reset-toggle-wrap {
  display: flex;
  justify-content: flex-start;
}
.auth-reset-toggle-btn {
  width: auto;
}

/* v1.2 bright landing refresh. */
.shell:has(.landing-v2-shell) {
  min-height: 100dvh;
  background:
    linear-gradient(180deg, #f8fbff 0%, #eef5fb 46%, #f7fafc 100%);
}
.landing-v2-shell {
  grid-template-columns: minmax(0, 1fr) minmax(360px, 420px);
  gap: 22px;
  width: min(1440px, calc(100vw - 32px));
  margin: 0 auto;
  padding: 22px 0 34px;
  font-family: Pretendard, "Noto Sans KR", Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.landing-v2-shell .auth-hero {
  gap: 16px;
  padding: 28px;
  border-color: #cfe1f3;
  border-radius: 16px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98) 0%, rgba(241, 248, 255, 0.96) 56%, rgba(240, 253, 244, 0.86) 100%);
  box-shadow: 0 18px 44px rgba(15, 23, 42, 0.08);
}
.landing-v2-shell .auth-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
