    radial-gradient(circle at 35% 35%, var(--logo-alert-primary), transparent 34%),
    radial-gradient(circle at 72% 42%, var(--logo-alert-secondary), transparent 30%),
    radial-gradient(circle at 50% 78%, var(--logo-alert-accent), transparent 40%);
  filter: blur(14px);
  transform: scale(1);
  animation: logoAuroraDrift 14s ease-in-out infinite alternate;
}
.logo-stage::after {
  inset: 14%;
  border: 1px solid var(--logo-alert-ring);
  box-shadow:
    0 0 40px var(--logo-alert-glow),
    inset 0 0 24px rgba(255, 255, 255, 0.12);
  opacity: 0.8;
  animation: logoHaloPulse 8s ease-in-out infinite;
}
.logo-stage-orbit,
.logo-stage-particles {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
}
.logo-stage-orbit {
  inset: 10%;
  border-radius: 999px;
  background:
    linear-gradient(110deg, transparent 18%, rgba(255, 255, 255, 0.14) 32%, transparent 48%),
    linear-gradient(280deg, transparent 58%, rgba(134, 239, 172, 0.18) 72%, transparent 88%);
  filter: blur(1px);
  mix-blend-mode: screen;
  animation: logoLightSweep 10s linear infinite;
}
.logo-stage-particles {
  inset: 16%;
  background:
    radial-gradient(circle at 16% 28%, rgba(255, 255, 255, 0.78) 0 1px, transparent 1.6px),
    radial-gradient(circle at 74% 24%, rgba(187, 247, 208, 0.72) 0 1.2px, transparent 1.8px),
    radial-gradient(circle at 62% 72%, rgba(255, 255, 255, 0.54) 0 1px, transparent 1.5px),
    radial-gradient(circle at 26% 78%, rgba(110, 231, 183, 0.52) 0 1.2px, transparent 1.8px);
  opacity: 0.85;
  animation: logoParticlesFloat 12s ease-in-out infinite alternate;
}
.logo-stage-sidebar {
  width: 136px;
  min-height: 108px;
  margin: 0 auto 4px;
}
.logo-stage-reveal-meter {
  position: absolute;
  left: 16%;
  right: 16%;
  bottom: 10px;
  height: 3px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
  opacity: 0.85;
  pointer-events: none;
  z-index: 3;
}
.logo-stage-reveal-meter > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(167, 243, 208, 0.22), rgba(74, 222, 128, 0.92));
  box-shadow: 0 0 18px rgba(74, 222, 128, 0.24);
  transition: width 160ms ease;
}
.logo-stage-easter-stack {
  position: absolute;
  left: 50%;
  bottom: 8px;
  z-index: 4;
  display: grid;
  gap: 3px;
  width: auto;
  max-width: min(150px, calc(100vw - 56px));
  transform: translate(-50%, 100%);
  pointer-events: none;
}
.logo-stage-critical-star {
  position: absolute;
  inset: 12%;
  z-index: 1;
  pointer-events: none;
  opacity: 0;
  transition: opacity 220ms ease;
}
.logo-stage-critical-star::before,
.logo-stage-critical-star::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 8%;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  transform: translate(-50%, -50%);
}
.logo-stage-critical-star::before {
  background: radial-gradient(circle, rgba(255, 255, 255, 0.95) 0 22%, rgba(248, 113, 113, 0.94) 30%, rgba(248, 113, 113, 0.14) 72%, transparent 100%);
  box-shadow:
    0 0 8px rgba(248, 113, 113, 0.52),
    0 0 18px rgba(239, 68, 68, 0.32);
}
.logo-stage-critical-star::after {
  width: 18px;
  height: 18px;
  background:
    linear-gradient(90deg, transparent 46%, rgba(254, 202, 202, 0.85) 50%, transparent 54%),
    linear-gradient(0deg, transparent 46%, rgba(254, 202, 202, 0.82) 50%, transparent 54%);
  opacity: 0.8;
}
.logo-stage-easter-egg {
  display: grid;
  gap: 2px;
  padding: 7px 10px;
  border-radius: 999px;
  border: 1px solid rgba(167, 243, 208, 0.28);
  background: rgba(248, 250, 252, 0.94);
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.12);
  color: var(--text);
  text-align: center;
  backdrop-filter: blur(12px);
  justify-items: center;
  min-width: 0;
}
.logo-stage-easter-egg strong {
  font-size: 10px;
  line-height: 1.2;
  letter-spacing: 0.1em;
  white-space: nowrap;
}
.logo-stage-easter-egg span,
.logo-stage-easter-egg code {
  font-size: 11px;
  line-height: 1.4;
}
.logo-stage-easter-egg.is-signature {
  background:
    linear-gradient(135deg, rgba(240, 253, 244, 0.96), rgba(236, 253, 245, 0.94)),
    rgba(255, 255, 255, 0.96);
  padding-inline: 12px;
}
.logo-stage-easter-egg.is-terminal {
  width: auto;
  max-width: min(148px, calc(100vw - 56px));
  padding: 5px 9px;
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.96), rgba(17, 24, 39, 0.94));
  border-color: rgba(74, 222, 128, 0.32);
  color: #dcfce7;
  text-align: center;
  justify-items: center;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.16);
}
.logo-stage-easter-egg.is-terminal strong {
  font-size: 9px;
  line-height: 1.2;
  letter-spacing: 0.08em;
  white-space: normal;
  word-break: break-word;
}
.logo-stage.is-quota-calm {
  --logo-alert-glow: rgba(34, 197, 94, 0.12);
  --logo-alert-ring: rgba(187, 247, 208, 0.42);
  --logo-alert-primary: rgba(110, 231, 183, 0.32);
  --logo-alert-secondary: rgba(34, 197, 94, 0.26);
  --logo-alert-accent: rgba(59, 130, 246, 0.14);
}
.logo-stage.is-quota-warn {
  --logo-alert-glow: rgba(234, 179, 8, 0.18);
  --logo-alert-ring: rgba(253, 224, 71, 0.4);
  --logo-alert-primary: rgba(253, 224, 71, 0.28);
  --logo-alert-secondary: rgba(251, 191, 36, 0.24);
  --logo-alert-accent: rgba(250, 204, 21, 0.18);
}
.logo-stage.is-quota-hot {
  --logo-alert-glow: rgba(249, 115, 22, 0.22);
  --logo-alert-ring: rgba(253, 186, 116, 0.48);
  --logo-alert-primary: rgba(251, 146, 60, 0.3);
  --logo-alert-secondary: rgba(249, 115, 22, 0.28);
  --logo-alert-accent: rgba(251, 191, 36, 0.18);
  animation: logoLoadDrift 5.8s ease-in-out infinite;
}
.logo-stage.is-quota-critical {
  --logo-alert-glow: rgba(239, 68, 68, 0.28);
  --logo-alert-ring: rgba(252, 165, 165, 0.48);
  --logo-alert-primary: rgba(248, 113, 113, 0.34);
  --logo-alert-secondary: rgba(239, 68, 68, 0.3);
  --logo-alert-accent: rgba(251, 146, 60, 0.18);
  filter: saturate(1.08);
  animation: logoLoadDriftCritical 4.2s ease-in-out infinite;
}
.logo-stage.is-quota-critical .logo-stage-critical-star {
  opacity: 0.96;
  animation: logoCriticalStarOrbit 8.4s linear infinite;
}
.logo-stage.is-quota-hot .logo-stage-orbit,
.logo-stage.is-quota-critical .logo-stage-orbit {
  animation-duration: 7s;
}
.logo-stage.is-quota-critical .logo-stage-particles {
  animation-duration: 7.4s;
}
.logo-stage.is-quota-warn .terminal-lab-logo-core {
  stroke: rgba(234, 179, 8, 0.92);
}
.logo-stage.is-quota-warn .brand-logo,
.logo-stage.is-quota-warn .hero-logo {
  filter: saturate(1.02) drop-shadow(0 0 14px rgba(250, 204, 21, 0.12));
}
.logo-stage.is-quota-hot .terminal-lab-logo-core {
  stroke: rgba(249, 115, 22, 0.94);
}
.logo-stage.is-quota-hot .brand-logo,
.logo-stage.is-quota-hot .hero-logo {
  filter: saturate(1.04) hue-rotate(-8deg) drop-shadow(0 0 16px rgba(249, 115, 22, 0.18));
}
.logo-stage.is-quota-critical .terminal-lab-logo-core {
  stroke: rgba(239, 68, 68, 0.95);
}
.logo-stage.is-quota-critical .brand-logo,
.logo-stage.is-quota-critical .hero-logo {
  filter: saturate(1.08) hue-rotate(-16deg) drop-shadow(0 0 18px rgba(248, 113, 113, 0.24));
}
.logo-stage.is-quota-hot .terminal-lab-logo-node,
.logo-stage.is-quota-critical .terminal-lab-logo-node {
  stroke: rgba(248, 250, 252, 0.86);
  filter: drop-shadow(0 0 12px rgba(251, 146, 60, 0.34));
}
.logo-stage.is-quota-critical .terminal-lab-logo-node {
  filter: drop-shadow(0 0 12px rgba(248, 113, 113, 0.42));
}
.logo-stage.is-signature-visible {
  transform: translateY(-2px) scale(1.01);
}
.logo-stage.is-terminal-visible::after {
  box-shadow:
    0 0 48px rgba(34, 197, 94, 0.18),
    inset 0 0 24px rgba(255, 255, 255, 0.12);
}
.logo-stage-sidebar .brand-logo {
