}
.terminal-lab-logo {
  overflow: visible;
}
.terminal-lab-logo-backdrop {
  opacity: 0.96;
}
.terminal-lab-logo-glow {
  animation: terminalLabLogoGlow 8s ease-in-out infinite alternate;
}
.terminal-lab-logo-halo {
  fill: none;
  stroke: rgba(187, 247, 208, 0.34);
  stroke-width: 1.2;
  stroke-dasharray: 3 8;
  animation: terminalLabLogoHalo 18s linear infinite;
}
.terminal-lab-logo-grid path {
  fill: none;
  stroke: rgba(167, 243, 208, 0.18);
  stroke-width: 1;
  stroke-linecap: round;
}
.terminal-lab-logo-orbit-group {
  transform-origin: 110px 110px;
}
.terminal-lab-logo-orbit-group-a {
  animation: terminalLabOrbitSpinA 22s linear infinite;
}
.terminal-lab-logo-orbit-group-b {
  animation: terminalLabOrbitSpinB 28s linear infinite reverse;
}
.terminal-lab-logo-orbit {
  fill: none;
  stroke: url(#terminalLabOrbitStroke);
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-dasharray: 16 12 6 10;
  opacity: 0.92;
}
.terminal-lab-logo-orbit.is-secondary {
  stroke: url(#terminalLabArcStroke);
  stroke-width: 1.8;
  stroke-dasharray: 12 10 4 12;
  opacity: 0.82;
}
.terminal-lab-logo-node {
  fill: #f0fdf4;
  stroke: rgba(16, 185, 129, 0.86);
  stroke-width: 2;
  filter: drop-shadow(0 0 10px rgba(74, 222, 128, 0.32));
}
.terminal-lab-logo-node-a,
.terminal-lab-logo-node-c {
  animation: terminalLabNodePulse 6.2s ease-in-out infinite;
}
.terminal-lab-logo-node-b,
.terminal-lab-logo-node-d {
  animation: terminalLabNodePulse 7.4s ease-in-out infinite 1.2s;
}
.terminal-lab-logo-core-shell {
  fill: rgba(15, 23, 42, 0.54);
  stroke: rgba(187, 247, 208, 0.42);
  stroke-width: 1.5;
}
.terminal-lab-logo-core {
  fill: rgba(8, 47, 73, 0.88);
  stroke: rgba(34, 197, 94, 0.92);
  stroke-width: 2.2;
}
.terminal-lab-logo-terminal-mark,
.terminal-lab-logo-terminal-line {
  fill: none;
  stroke: #f0fdf4;
  stroke-width: 4.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.terminal-lab-logo-stars circle {
  fill: rgba(255, 255, 255, 0.82);
  opacity: 0.74;
  animation: terminalLabStarTwinkle 5.8s ease-in-out infinite;
}
.terminal-lab-logo-stars circle:nth-child(2) {
  animation-delay: 1.1s;
}
.terminal-lab-logo-stars circle:nth-child(3) {
  animation-delay: 2.1s;
}
.terminal-lab-logo-stars circle:nth-child(4) {
  animation-delay: 3.4s;
}

@keyframes logoAuroraDrift {
  0% {
    transform: scale(0.96) translate3d(-6px, -4px, 0);
    filter: blur(14px) hue-rotate(0deg);
  }
  100% {
    transform: scale(1.05) translate3d(8px, 6px, 0);
    filter: blur(18px) hue-rotate(10deg);
  }
}

@keyframes logoHaloPulse {
  0%, 100% {
    opacity: 0.55;
    transform: scale(0.98);
  }
  50% {
    opacity: 0.92;
    transform: scale(1.03);
  }
}

@keyframes logoLightSweep {
  0% {
    transform: rotate(-8deg) translateX(-10px);
    opacity: 0.18;
  }
  50% {
    opacity: 0.4;
  }
  100% {
    transform: rotate(7deg) translateX(12px);
    opacity: 0.18;
  }
}

@keyframes logoParticlesFloat {
  0% {
    transform: translate3d(-2px, 2px, 0) scale(0.98);
  }
  100% {
    transform: translate3d(3px, -3px, 0) scale(1.02);
  }
}

@keyframes logoLoadDrift {
  0%, 100% {
    transform: translate3d(0, 0, 0) rotate(0deg);
  }
  20% {
    transform: translate3d(-0.8px, 0.5px, 0) rotate(-0.18deg);
  }
  45% {
    transform: translate3d(0.9px, -0.6px, 0) rotate(0.2deg);
  }
  70% {
    transform: translate3d(-0.5px, -0.4px, 0) rotate(-0.12deg);
  }
}

@keyframes logoLoadDriftCritical {
  0%, 100% {
    transform: translate3d(0, 0, 0) rotate(0deg);
  }
  18% {
    transform: translate3d(-1.1px, 0.7px, 0) rotate(-0.24deg);
  }
  40% {
    transform: translate3d(1.3px, -0.8px, 0) rotate(0.28deg);
  }
  62% {
    transform: translate3d(-0.8px, -0.6px, 0) rotate(-0.18deg);
  }
  82% {
    transform: translate3d(0.7px, 0.4px, 0) rotate(0.14deg);
  }
}

@keyframes logoCriticalStarOrbit {
  0% {
    transform: rotate(0deg);
    opacity: 0.78;
  }
  25% {
    opacity: 1;
  }
  50% {
    opacity: 0.86;
  }
  75% {
    opacity: 1;
  }
  100% {
    transform: rotate(360deg);
    opacity: 0.78;
  }
}

@keyframes terminalLabOrbitSpinA {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes terminalLabOrbitSpinB {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes terminalLabNodePulse {
  0%, 100% {
    transform: scale(0.94);
    opacity: 0.82;
  }
  50% {
    transform: scale(1.14);
    opacity: 1;
  }
}

@keyframes terminalLabLogoGlow {
  0% {
    opacity: 0.72;
    transform: scale(0.96);
  }
  100% {
    opacity: 1;
    transform: scale(1.05);
  }
}

@keyframes terminalLabLogoHalo {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes terminalLabStarTwinkle {
  0%, 100% {
    opacity: 0.26;
  }
  50% {
    opacity: 0.92;
  }
}

