}
@keyframes header-bell-ring {
  0%, 100% { transform: rotate(0deg); }
  4% { transform: rotate(16deg); }
  8% { transform: rotate(-14deg); }
  12% { transform: rotate(10deg); }
  16% { transform: rotate(-8deg); }
  20% { transform: rotate(4deg); }
  24% { transform: rotate(0deg); }
}
@keyframes header-bell-fresh-ring {
  0%, 100% { transform: rotate(0deg) scale(1); }
  12% { transform: rotate(24deg) scale(1.05); }
  24% { transform: rotate(-22deg) scale(1.06); }
  36% { transform: rotate(18deg) scale(1.04); }
  48% { transform: rotate(-14deg) scale(1.02); }
  60% { transform: rotate(10deg) scale(1.01); }
  72% { transform: rotate(-6deg) scale(1); }
}
