  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}
.course-detail-section-nav button:hover,
.course-detail-section-nav button:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 22%, var(--border));
  color: var(--text);
}
.course-learning-workbench {
  display: grid;
  grid-template-columns: minmax(220px, 0.34fr) minmax(0, 1fr);
  gap: 12px;
  min-height: clamp(430px, calc(100dvh - 315px), 680px);
  max-height: calc(100dvh - 250px);
  margin: 0 0 14px;
  padding: 12px;
  border: 1px solid #dbe3ee;
  border-radius: 16px;
  background: #f8fafc;
}
.course-learning-resource-rail,
.course-learning-viewer {
  min-height: 0;
  min-width: 0;
  border: 1px solid #dbe3ee;
  border-radius: 12px;
  background: #ffffff;
}
.course-learning-resource-rail {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
}
.course-learning-resource-head {
  display: grid;
  gap: 4px;
  padding: 12px;
  border-bottom: 1px solid #eef2f7;
}
.course-learning-resource-list {
  display: grid;
  align-content: start;
  gap: 8px;
  min-height: 0;
  overflow: auto;
  padding: 10px;
}
.course-learning-resource-card {
  display: grid;
  grid-template-columns: minmax(66px, auto) minmax(0, 1fr);
  gap: 9px;
  align-items: center;
  width: 100%;
  padding: 10px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #ffffff;
  color: #0f172a;
  text-align: left;
  cursor: pointer;
}
.course-learning-resource-card:hover,
.course-learning-resource-card.is-active {
  border-color: #a8bdd8;
  background: #f8fbff;
}
.course-learning-resource-card.is-active {
  box-shadow: inset 3px 0 0 #2563eb;
}
.course-learning-resource-kind {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 8px;
  border: 1px solid #dbe3ee;
  border-radius: 999px;
  background: #f8fafc;
  color: #475569;
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
}
.course-learning-resource-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.course-learning-resource-copy strong,
.course-learning-resource-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.course-learning-resource-copy small {
  color: #64748b;
  font-size: 12px;
}
.course-learning-resource-empty {
  display: grid;
  gap: 6px;
  padding: 12px;
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  background: #f8fafc;
  color: #475569;
  line-height: 1.45;
}
.course-learning-resource-empty strong {
  color: #0f172a;
  font-size: 13px;
}
.course-learning-resource-empty small {
  color: #64748b;
}
.course-learning-viewer {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
}
.course-learning-viewer-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border-bottom: 1px solid #eef2f7;
}
.course-learning-viewer-head > div:first-child {
  display: grid;
  gap: 5px;
  min-width: 0;
}
.course-learning-viewer-head strong {
  color: #0f172a;
  font-size: 16px;
  line-height: 1.25;
}
.course-learning-viewer-head small {
  color: #64748b;
  line-height: 1.35;
}
.course-learning-viewer-body {
  min-height: 0;
  overflow: auto;
  padding: 14px;
}
.course-learning-viewer-body.is-document {
  display: grid;
  grid-template-rows: minmax(0, 1fr);
  gap: 10px;
  padding: 0;
}
.course-learning-viewer-body.is-document.is-pdf {
  padding: 10px;
  background: #f8fafc;
}
.course-learning-viewer-body.is-document.has-note {
  grid-template-rows: auto minmax(0, 1fr);
}
.course-learning-viewer-body.is-media {
  display: grid;
  align-content: start;
  gap: 12px;
}
.course-learning-viewer-body.is-media .video-embed {
  max-height: min(58dvh, 520px);
}
.course-document-note {
  margin: 12px 12px 0;
  padding: 9px 10px;
  border: 1px solid #dbe3ee;
  border-radius: 8px;
  background: #f8fafc;
  color: #64748b;
  font-size: 12px;
  line-height: 1.5;
}
.course-document-frame {
  width: 100%;
  height: 100%;
  align-self: stretch;
  min-height: 420px;
  border: 0;
  background: #ffffff;
}
.course-document-frame.is-pdf {
  min-height: clamp(520px, calc(100dvh - 310px), 860px);
  border: 1px solid #dbe3ee;
  border-radius: 8px;
  background: #f1f5f9;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.78);
}
.course-learning-empty {
  display: grid;
  place-items: center;
  gap: 10px;
  min-height: 280px;
  padding: 24px;
  color: #64748b;
  text-align: center;
}
.course-detail-anchor {
  scroll-margin-top: 190px;
}
.detail-block .card-label {
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: 0;
  color: var(--text);
}
.detail-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}
.detail-section-head > div {
  min-width: 0;
}
.simple-info-block {
  border-radius: 16px;
  border: 1px solid transparent;
  background: #fff;
  padding: 14px;
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.04);
}
.course-detail-copy {
  line-height: 1.7;
  white-space: pre-wrap;
  word-break: break-word;
}
.online-course-banner {
  gap: 10px;
  border: 1px solid transparent;
  background: linear-gradient(135deg, rgba(248, 250, 252, 0.96) 0%, rgba(241, 245, 249, 0.94) 100%);
  box-shadow: 0 14px 28px rgba(15, 23, 42, 0.05);
}
.online-course-banner strong {
  font-size: 16px;
  line-height: 1.6;
  color: #111827;
}
.course-recordings-block {
  gap: 14px;
  border-color: rgba(37, 99, 235, 0.16);
  background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
}
.course-recording-list {
  display: grid;
  gap: 8px;
}
.course-recording-row {
  display: grid;
  grid-template-columns: 112px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid #dbe7f5;
  border-radius: 12px;
  background: #fff;
  color: #111827;
  text-decoration: none;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}
.course-recording-row:hover {
  border-color: rgba(37, 99, 235, 0.42);
  box-shadow: 0 12px 24px rgba(37, 99, 235, 0.08);
  transform: translateY(-1px);
}
.course-recording-date {
  display: inline-flex;
  justify-content: center;
  min-width: 96px;
  padding: 7px 10px;
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}
.course-recording-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}
.course-recording-copy strong,
.course-recording-copy small {
  overflow-wrap: anywhere;
}
.course-recording-copy small {
  color: #64748b;
  line-height: 1.5;
}
.detail-list {
  margin: 0;
  padding-left: 18px;
  display: grid;
  gap: 6px;
}
.guide-preview {
  border-radius: 12px;
}
.course-chip {
  background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
  border-color: transparent;
  color: var(--primary);
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.04);
}

.flavor-badge-list {
  display: inline-flex;
  gap: 6px;
  flex-wrap: wrap;
  align-items: center;
}
.portal-list-item .flavor-badge-list {
  display: flex;
  margin-top: 10px;
}

.flavor-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
  color: #475569;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  box-shadow: 0 8px 16px rgba(15, 23, 42, 0.04);
}
.portal-list-item .flavor-badge {
  margin-top: 0;
}

.flavor-badge.is-gpu {
  border-color: transparent;
  background: linear-gradient(180deg, #f8fafc 0%, #eef2f7 100%);
  color: #475569;
}

.flavor-badge.is-vgpu {
  border-color: transparent;
  background: linear-gradient(180deg, #f8fafc 0%, #eef2f7 100%);
  color: #475569;
}

.flavor-badge.is-highperf {
  border-color: transparent;
  background: linear-gradient(180deg, #f8fafc 0%, #eef2f7 100%);
  color: #475569;
}

.flavor-inline-row,
.flavor-selection-hint {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.course-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.course-detail,
.terminal-layout { padding: 16px; }
.detail-block { margin-top: 18px; }
.guide-page {
  display: grid;
  gap: 16px;
}
.guide-page-head {
  margin-bottom: 0;
}
.guide-page-body {
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fff;
}
.guide-preview {
  max-height: 260px;
  overflow: auto;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fbfcfe;
}
.markdown-guide-shell.has-toc {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 16px;
  align-items: start;
}
.guide-toc {
  position: sticky;
  top: 16px;
  display: grid;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fbfcfe;
}
.guide-toc-list {
  display: grid;
  gap: 6px;
}
.guide-toc-item {
  color: var(--text);
  text-decoration: none;
  font-size: 13px;
}
.guide-toc-item.level-2 {
  padding-left: 10px;
}
.guide-toc-item.level-3 {
  padding-left: 20px;
}
.markdown-guide { display: grid; gap: 10px; }
.markdown-guide h4,
.markdown-guide h5,
.markdown-guide h6 { margin: 0; color: var(--text); }
.markdown-guide p { margin: 0; line-height: 1.7; }
.markdown-guide strong { color: var(--text); font-weight: 700; }
.markdown-code-wrap {
  display: grid;
  gap: 6px;
}
.markdown-code-toolbar {
  display: flex;
  justify-content: flex-end;
}
.markdown-code {
  margin: 0;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #f6f8fb;
  overflow: auto;
  font-size: 12px;
  line-height: 1.6;
}
.markdown-guide code {
  padding: 1px 5px;
  border-radius: 4px;
  background: #eef2f8;
  font-family: Consolas, "Courier New", monospace;
  font-size: 12px;
}
.markdown-code code { padding: 0; background: transparent; }
.detail-list { margin: 0; padding-left: 18px; line-height: 1.7; }

.material-link {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 12px 0;
  border-top: 1px solid rgba(226, 232, 240, 0.9);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  text-decoration: none;
  box-shadow: none;
  transition: border-color 0.18s ease, background-color 0.18s ease;
}
.material-title {
  flex: 1;
  min-width: 0;
  line-height: 1.5;
}
.material-link:hover {
  transform: none;
  box-shadow: none;
}
.material-link strong { color: #111827; }
.material-row {
  align-items: center;
}
.material-list > .material-row:first-child {
  border-top: 0;
  padding-top: 0;
}
.material-list > .material-row:last-child {
  padding-bottom: 0;
}
.portal-list-item p {
  font-size: 13px;
  line-height: 1.45;
}
.material-actions {
  display: flex;
  gap: 8px;
  flex-wrap: nowrap;
  flex-shrink: 0;
  align-items: center;
}
.mini-link-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  padding: 6px 10px;
  white-space: nowrap;
}
.guide-preview-inline {
  max-height: none;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

@media (max-width: 720px) {
  .course-learning-workbench {
    grid-template-columns: 1fr;
    min-height: 0;
    max-height: none;
  }

  .course-learning-resource-list {
    max-height: 220px;
  }

  .course-learning-viewer {
    min-height: 420px;
  }

  .course-learning-viewer-head {
    align-items: stretch;
    flex-direction: column;
  }

  .material-link {
    flex-direction: column;
    align-items: stretch;
  }

  .material-actions {
    width: 100%;
    flex-wrap: wrap;
    justify-content: flex-start;
  }
  .detail-section-head {
    flex-direction: column;
    align-items: stretch;
  }

  .course-recording-row {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .course-recording-date {
    justify-content: flex-start;
    width: fit-content;
  }
}

.lab-box {
  display: grid;
  gap: 10px;
  padding: 12px;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 6px;
}
.course-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.lab-summary {
  display: grid;
  gap: 4px;
  color: var(--muted);
  font-size: 13px;
}

.terminal-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}
.terminal-embed {
  position: relative;
  min-height: 560px;
  overflow: hidden;
  background: #111827;
  border-radius: 10px;
}
.terminal-console-frame {
  position: relative;
  min-width: 0;
}
.terminal-shell {
  padding: 0;
}
.terminal-view-shell.is-enrollment-disabled {
  position: relative;
  min-height: 640px;
  isolation: isolate;
}
.terminal-view-shell.is-enrollment-disabled > :not(.terminal-enrollment-disabled-overlay) {
  opacity: 0.3;
  filter: grayscale(0.9);
  pointer-events: none;
  user-select: none;
}
.terminal-enrollment-disabled-overlay {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(120px, 22vh, 220px) 24px 48px;
  background: rgba(241, 245, 249, 0.78);
  backdrop-filter: blur(3px);
}
.terminal-enrollment-disabled-panel {
  display: grid;
  justify-items: center;
  gap: 12px;
  width: min(520px, 100%);
  padding: 30px 32px;
  border: 1px solid rgba(148, 163, 184, 0.42);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.96);
  color: #1e293b;
  text-align: center;
  box-shadow: 0 24px 64px rgba(15, 23, 42, 0.18);
}
.terminal-enrollment-disabled-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 999px;
  background: #e2e8f0;
  color: #475569;
  font-size: 26px;
  font-weight: 800;
}
.terminal-enrollment-disabled-panel strong {
  font-size: clamp(22px, 3vw, 30px);
  line-height: 1.3;
}
.terminal-enrollment-disabled-panel p {
  margin: 0;
  color: #64748b;
  font-size: 15px;
  line-height: 1.7;
}
.terminal-embed.is-fixed {
  min-height: 560px;
}
.terminal-embed.is-embedded {
  min-height: 380px;
}
.terminal-root {
  width: 100%;
  overflow: hidden;
}
.terminal-root.is-fixed {
  min-height: 560px;
}
.terminal-root.is-embedded {
  min-height: 380px;
}
.terminal-embed.is-console-blocked .terminal-root {
  opacity: 0.26;
  pointer-events: none;
  user-select: none;
}
.terminal-console-status-overlay {
  position: absolute;
  inset: 0;
  z-index: 12;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at 50% 12%, rgba(37, 99, 235, 0.16), transparent 42%),
    linear-gradient(180deg, rgba(8, 15, 30, 0.76), rgba(8, 15, 30, 0.96));
  color: #e5e7eb;
}
.terminal-console-status-card {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 16px;
  overflow: hidden;
  width: min(640px, 100%);
  padding: 22px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 20px;
  background:
    linear-gradient(145deg, rgba(20, 31, 52, 0.97), rgba(12, 21, 38, 0.98)),
    #0f172a;
  box-shadow:
    0 32px 90px rgba(2, 6, 23, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(22px) saturate(1.12);
}
.terminal-console-status-card::before {
  position: absolute;
  inset: 0 0 auto;
  height: 2px;
  background: linear-gradient(90deg, transparent 4%, #60a5fa 48%, #22d3ee 72%, transparent 96%);
  content: "";
  opacity: 0.88;
}
.terminal-console-status-overlay.is-ready .terminal-console-status-card {
  border-color: rgba(96, 165, 250, 0.36);
}
.terminal-console-status-overlay.is-wait .terminal-console-status-card {
  border-color: rgba(251, 191, 36, 0.34);
}
.terminal-console-status-overlay.is-error .terminal-console-status-card {
  border-color: rgba(248, 113, 113, 0.38);
}
.terminal-console-status-loader {
  display: inline-flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
  width: 52px;
  height: 52px;
  padding: 11px;
  border: 1px solid rgba(96, 165, 250, 0.28);
  border-radius: 16px;
  background: linear-gradient(145deg, rgba(37, 99, 235, 0.2), rgba(30, 41, 59, 0.74));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 10px 30px rgba(2, 6, 23, 0.24);
}
.terminal-console-status-loader span {
  width: 6px;
  min-height: 10px;
  border-radius: 999px;
  background: linear-gradient(180deg, #67e8f9, #60a5fa);
  animation: terminal-console-loader-pulse 1.05s ease-in-out infinite;
}
.terminal-console-status-loader span:nth-child(2) {
  min-height: 18px;
  animation-delay: 0.12s;
}
.terminal-console-status-loader span:nth-child(3) {
  min-height: 26px;
  animation-delay: 0.24s;
}
.terminal-console-status-loader .terminal-console-status-main-icon {
  width: auto;
  min-height: 0;
  border-radius: 0;
  background: transparent;
  color: #bfdbfe;
  font-size: 24px;
  line-height: 1;
  animation: terminal-readiness-icon-bob 1.15s ease-in-out infinite;
}
.terminal-console-status-overlay.is-switching .terminal-console-status-main-icon {
  transform-origin: 48% 52%;
  animation: terminal-console-switch-flight 1.25s ease-in-out infinite;
}
.terminal-console-status-overlay.is-switching .terminal-console-status-card::before {
  animation: terminal-console-switch-scan 1.8s linear infinite;
}
.terminal-console-status-overlay.is-wait .terminal-console-status-loader span {
  background: #fbbf24;
}
.terminal-console-status-overlay.is-wait .terminal-console-status-loader .terminal-console-status-main-icon {
  background: transparent;
  color: #fde68a;
}
.terminal-console-status-overlay.is-error .terminal-console-status-loader span {
  background: #f87171;
  animation: none;
}
.terminal-console-status-overlay.is-error .terminal-console-status-loader .terminal-console-status-main-icon {
  background: transparent;
  color: #fecaca;
}
.terminal-console-status-copy {
  display: grid;
  gap: 8px;
  min-width: 0;
}
.terminal-console-status-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.terminal-console-status-meta .status-chip {
  gap: 7px;
  min-height: 25px;
  padding: 4px 10px;
  border-color: rgba(96, 165, 250, 0.26);
  background: rgba(37, 99, 235, 0.14);
  color: #bfdbfe;
}
.terminal-console-status-meta .status-chip i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: #60a5fa;
  box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.12);
  animation: terminal-readiness-icon-bob 1.15s ease-in-out infinite;
}
.terminal-console-status-overlay.is-wait .terminal-console-status-meta .status-chip i {
  background: #fbbf24;
  box-shadow: 0 0 0 4px rgba(251, 191, 36, 0.12);
}
.terminal-console-status-overlay.is-error .terminal-console-status-meta .status-chip i {
  background: #f87171;
  box-shadow: 0 0 0 4px rgba(248, 113, 113, 0.12);
  animation: none;
