  left: calc(16.666% + 6px);
  width: var(--flow-progress, 0%);
  max-width: calc(66.666% - 12px);
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, #3b82f6, #22d3ee);
  box-shadow: 0 0 12px rgba(34, 211, 238, 0.3);
  content: "";
  transition: width 360ms ease;
}
