.terminal-action-menu[open]::after {
  content: "";
  position: absolute;
  top: calc(100% - 2px);
  right: -8px;
  z-index: 351;
  width: max(calc(100% + 16px), 264px);
  height: 28px;
  pointer-events: auto;
}
