.portal-status-wrap {
  width: 100%;
}

.portal-status-badge {
  --portal-status-accent: #16a34a;
  --portal-status-accent-soft: rgba(34, 197, 94, 0.12);
  --portal-status-accent-border: rgba(34, 197, 94, 0.28);
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  overflow: hidden;
  width: 100%;
  margin-top: 10px;
  padding: 10px 10px 11px;
  border: 1px solid var(--portal-status-accent-border);
  border-radius: 14px;
  appearance: none;
  background:
    radial-gradient(circle at 12% 20%, var(--portal-status-accent-soft), transparent 38%),
    linear-gradient(145deg, #ffffff, #f8fafc);
  color: #334155;
  cursor: pointer;
  font: inherit;
  text-align: left;
  box-shadow:
    0 10px 24px rgba(15, 23, 42, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}

.portal-status-badge::after {
  position: absolute;
  right: auto;
  bottom: 0;
  left: 0;
  width: var(--portal-quota-level, 0%);
  height: 3px;
  border-radius: 0 999px 999px 0;
  background: linear-gradient(90deg, var(--portal-status-accent), #38bdf8);
  box-shadow: 0 -2px 10px var(--portal-status-accent-soft);
  content: "";
  transition: width 420ms ease;
}

.portal-status-badge.is-quota-warn {
  --portal-status-accent: #d97706;
  --portal-status-accent-soft: rgba(245, 158, 11, 0.13);
  --portal-status-accent-border: rgba(245, 158, 11, 0.32);
}

.portal-status-badge.is-quota-hot {
  --portal-status-accent: #ea580c;
  --portal-status-accent-soft: rgba(249, 115, 22, 0.14);
  --portal-status-accent-border: rgba(249, 115, 22, 0.34);
}

.portal-status-badge.is-quota-critical {
  --portal-status-accent: #dc2626;
  --portal-status-accent-soft: rgba(239, 68, 68, 0.14);
  --portal-status-accent-border: rgba(239, 68, 68, 0.36);
}

.portal-status-badge:hover,
.portal-status-badge:focus-visible {
  border-color: var(--portal-status-accent);
  box-shadow:
    0 16px 30px rgba(15, 23, 42, 0.1),
    0 0 0 4px var(--portal-status-accent-soft);
  transform: translateY(-2px);
}

.portal-status-badge:active {
  transform: translateY(0) scale(0.99);
}

.portal-status-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.portal-status-title {
  min-width: 0;
  overflow: hidden;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: -0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portal-status-copy small {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  overflow: hidden;
  color: var(--portal-status-accent);
  font-size: 10px;
  font-weight: 900;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portal-status-mood > span {
  flex: 0 0 auto;
  font-size: 11px;
  filter: saturate(1.08);
  transform: translateY(-0.5px);
}

.portal-resource-dots {
  --portal-dot-color: #16a34a;
  --portal-dot-accent: #2563eb;
  --portal-dot-glow: rgba(34, 197, 94, 0.24);
  --portal-dot-speed: 2.8s;
  position: relative;
  display: grid;
  grid-template-columns: repeat(6, 4px);
  grid-auto-rows: 4px;
  gap: 2px;
  align-self: center;
  justify-content: center;
  width: 42px;
  height: 38px;
  padding: 9px 6px;
  overflow: hidden;
  border: 1px solid var(--portal-status-accent-border);
  border-radius: 13px;
  background:
    radial-gradient(circle at 25% 25%, rgba(255, 255, 255, 0.92), transparent 34%),
    linear-gradient(145deg, rgba(240, 253, 244, 0.96), rgba(248, 250, 252, 0.96));
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.72),
    0 0 0 4px var(--portal-dot-glow);
  transition: transform 0.24s ease, box-shadow 0.24s ease;
}

.portal-status-badge:hover .portal-resource-dots,
.portal-status-badge:focus-visible .portal-resource-dots {
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.84),
    0 0 0 5px var(--portal-dot-glow),
    0 10px 22px var(--portal-dot-glow);
  transform: rotate(-3deg) scale(1.05);
}

.portal-resource-dots::before,
.portal-resource-dots::after {
  content: "";
  position: absolute;
  inset: -10px;
  border-radius: 50%;
  background: conic-gradient(from 90deg, transparent 0 35%, rgba(37, 99, 235, 0.22) 46%, transparent 58% 100%);
  opacity: 0.75;
  animation: portal-resource-dot-orbit calc(var(--portal-dot-speed) * 2.4) linear infinite;
}

.portal-resource-dots::after {
  inset: -14px;
  background: conic-gradient(from 220deg, transparent 0 42%, rgba(22, 163, 74, 0.28) 50%, transparent 62% 100%);
  animation-direction: reverse;
  animation-duration: calc(var(--portal-dot-speed) * 3);
}

.portal-resource-dot {
  position: relative;
  z-index: 1;
  width: 4px;
  height: 4px;
  border-radius: 999px;
  background: var(--portal-dot-color);
  box-shadow: 0 0 8px var(--portal-dot-glow);
  opacity: 0.35;
  animation: portal-resource-dot-pulse var(--portal-dot-speed) ease-in-out infinite;
}

.portal-resource-dot:nth-child(3n) {
  background: var(--portal-dot-accent);
}

.portal-resource-dot:nth-child(4n) {
  transform-origin: center;
}

.portal-resource-dot.is-dot-1 { animation-delay: -0.1s; }
.portal-resource-dot.is-dot-2 { animation-delay: -0.9s; }
.portal-resource-dot.is-dot-3 { animation-delay: -1.7s; }
.portal-resource-dot.is-dot-4 { animation-delay: -0.5s; }
.portal-resource-dot.is-dot-5 { animation-delay: -1.3s; }
.portal-resource-dot.is-dot-6 { animation-delay: -2.1s; }
.portal-resource-dot.is-dot-7 { animation-delay: -1.1s; }
.portal-resource-dot.is-dot-8 { animation-delay: -0.3s; }
.portal-resource-dot.is-dot-9 { animation-delay: -1.9s; }
.portal-resource-dot.is-dot-10 { animation-delay: -0.7s; }
.portal-resource-dot.is-dot-11 { animation-delay: -1.5s; }
.portal-resource-dot.is-dot-12 { animation-delay: -2.3s; }
.portal-resource-dot.is-dot-13 { animation-delay: -1.8s; }
.portal-resource-dot.is-dot-14 { animation-delay: -0.6s; }
.portal-resource-dot.is-dot-15 { animation-delay: -1.4s; }
.portal-resource-dot.is-dot-16 { animation-delay: -2.2s; }
.portal-resource-dot.is-dot-17 { animation-delay: -1s; }
.portal-resource-dot.is-dot-18 { animation-delay: -0.2s; }

@keyframes portal-resource-dot-pulse {
  0%, 100% {
    opacity: 0.32;
    transform: translateY(0) scale(0.78);
  }
  42% {
    opacity: 1;
    transform: translateY(-2px) scale(1.42);
  }
  64% {
    opacity: 0.62;
    transform: translateY(1px) scale(0.96);
  }
}

@keyframes portal-resource-dot-orbit {
  to {
    transform: rotate(360deg);
  }
}

