/* v1.2 admin cleanup and platform simplification. */
.admin-cleanup-records {
  margin-top: 12px;
  border: 1px solid #dbe5f2;
  border-radius: 8px;
  background: #f8fafc;
}

.admin-cleanup-records summary {
  cursor: pointer;
  padding: 10px 12px;
  color: #1d4ed8;
  font-weight: 800;
}

.admin-cleanup-record-list {
  display: grid;
  gap: 8px;
  padding: 0 12px 12px;
}

.admin-cleanup-record-row {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) 120px 100px minmax(140px, 1fr);
  gap: 10px;
  align-items: center;
  padding: 9px 10px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: #fff;
  color: #0f172a;
}

.admin-cleanup-record-row span,
.admin-cleanup-record-row small {
  color: #475569;
}

.admin-platform-operations-details {
  margin-top: 14px;
  border: 1px solid #dbe5f2;
  border-radius: 10px;
  background: #fff;
}

.admin-platform-operations-details > summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  min-height: 44px;
  padding: 12px 14px;
  cursor: pointer;
  list-style: none;
}

.admin-platform-operations-details > summary::-webkit-details-marker {
  display: none;
}

.admin-platform-operations-details > summary strong {
  display: block;
  color: #0f172a;
}

.admin-platform-operations-details > summary small {
  display: block;
  margin-top: 3px;
  color: #64748b;
  font-weight: 600;
}

.admin-platform-operations-details > summary em {
  flex: 0 0 auto;
  border: 1px solid #bfdbfe;
  border-radius: 999px;
  padding: 4px 10px;
  background: #eff6ff;
  color: #1d4ed8;
  font-style: normal;
  font-weight: 800;
}

.admin-platform-operations-details[open] > summary em {
  color: #475569;
}

.admin-platform-operations-details[open] > summary em::before {
  content: "닫기";
}

.admin-platform-operations-details[open] > summary em {
  font-size: 0;
}

.admin-platform-operations-details[open] > summary em::before {
  font-size: 12px;
}

.admin-platform-operations-body {
  display: grid;
  gap: 14px;
  padding: 0 14px 14px;
}

/* v1.2 notice repair for both user and admin shells. */
.notice-view .notice-board.notice-board-timeline {
  display: grid;
  gap: 14px;
  border: 0;
  background: transparent;
}

.notice-view .notice-feature-card,
.notice-view .notice-timeline-card {
  position: relative;
  display: grid;
  gap: 10px;
  border: 1px solid #dbeafe;
  border-radius: 10px;
  padding: 16px 18px;
  background: #fff;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.04);
}

.notice-view .notice-feature-card {
  grid-template-columns: auto 1fr;
  background: linear-gradient(135deg, #eff6ff 0%, #fff 62%);
  border-color: #bfdbfe;
}

.notice-view .notice-feature-mark {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 16px;
  background: #2563eb;
  color: #fff;
  font-weight: 900;
}

.notice-view .notice-feature-head,
.notice-view .notice-timeline-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 4px;
}

.notice-view .notice-feature-head strong,
.notice-view .notice-timeline-head strong {
  color: #0f172a;
  font-size: 16px;
  line-height: 1.35;
}

.notice-view .notice-feature-head time,
.notice-view .notice-timeline-head time {
  flex: 0 0 auto;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.notice-view .notice-timeline-list {
  position: relative;
  display: grid;
  gap: 12px;
}

.notice-view .notice-timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 16px 1fr;
  gap: 12px;
}

.notice-view .notice-timeline-dot {
  width: 10px;
  height: 10px;
  margin-top: 18px;
  border: 2px solid #93c5fd;
  border-radius: 999px;
  background: #fff;
}

.notice-view .notice-body,
.notice-view .qna-post-body {
  color: #334155;
  line-height: 1.65;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.notice-view .admin-inline-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

@media (max-width: 760px) {
  .notice-view .notice-feature-card,
  .notice-view .notice-timeline-item {
    grid-template-columns: 1fr;
  }

  .notice-view .notice-feature-head,
  .notice-view .notice-timeline-head,
  .admin-platform-operations-details > summary {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-cleanup-record-row {
    grid-template-columns: 1fr;
  }
}

.ops-monitor-view {
  display: grid;
  gap: 16px;
}

.ops-monitor-hero {
  align-items: center;
  background: linear-gradient(135deg, #ffffff 0%, #f0f7ff 58%, #eefcf4 100%);
  border: 1px solid #cfe1f7;
  border-radius: 12px;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.08);
  display: flex;
  justify-content: space-between;
  min-height: 116px;
  padding: 22px;
}

.ops-monitor-hero h2 {
  color: #0f172a;
  font-size: 28px;
  letter-spacing: 0;
  margin: 4px 0 8px;
}

.ops-monitor-hero p {
  color: #475569;
  margin: 0;
}

.ops-monitor-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.ops-monitor-actions > span {
  color: #64748b;
  font-size: 13px;
}

.ops-monitor-summary {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.ops-monitor-summary article {
  background: #ffffff;
  border: 1px solid #d5e3f4;
  border-radius: 10px;
  display: grid;
  gap: 6px;
  min-height: 96px;
  padding: 16px;
}

.ops-monitor-summary span,
.ops-monitor-vm-meta,
.ops-monitor-vm-foot > span {
  color: #64748b;
  font-size: 13px;
}

.ops-monitor-summary strong {
  color: #0f172a;
  font-size: 28px;
}

.ops-monitor-summary small {
  color: #475569;
}

.ops-monitor-toolbar {
  align-items: center;
  background: #ffffff;
  border: 1px solid #d5e3f4;
  border-radius: 10px;
  display: grid;
  gap: 10px;
  grid-template-columns: 1fr auto;
  padding: 10px;
}

.ops-monitor-toolbar input {
  background: #ffffff;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  color: #0f172a;
  min-height: 42px;
  padding: 0 12px;
}

.ops-monitor-filter {
  display: flex;
  gap: 6px;
}

.ops-monitor-filter button {
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 999px;
  color: #334155;
  min-height: 36px;
  padding: 0 14px;
}

.ops-monitor-filter button.is-active {
  background: #0f172a;
  border-color: #0f172a;
  color: #ffffff;
}

.ops-monitor-layout {
  display: grid;
  gap: 12px;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 320px);
  max-width: 100%;
  overflow: hidden;
}

.ops-monitor-grid {
  align-content: start;
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 320px), 1fr));
  max-width: 100%;
  min-width: 0;
}

.ops-monitor-vm {
  align-items: flex-start;
  background: #ffffff;
  border: 1px solid #d5e3f4;
  border-radius: 12px;
  color: inherit;
  cursor: pointer;
  display: grid;
  gap: 12px;
  grid-template-columns: auto 1fr;
  min-height: 188px;
  min-width: 0;
  overflow: hidden;
  padding: 14px;
  text-align: left;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
  width: 100%;
}

.ops-monitor-vm:hover,
.ops-monitor-vm:focus-visible,
.ops-monitor-vm.is-selected {
  border-color: #60a5fa;
  box-shadow: 0 12px 28px rgba(37, 99, 235, 0.12);
  outline: none;
}

.ops-monitor-vm:hover {
  transform: translateY(-1px);
}

.ops-monitor-vm-icon {
  align-items: center;
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  border-radius: 12px;
  color: #1d4ed8;
  display: flex;
  font-size: 12px;
  font-weight: 800;
  height: 46px;
  min-width: 46px;
  justify-content: center;
  width: 46px;
}

.ops-monitor-vm-main {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.ops-monitor-vm-head {
  align-items: center;
  display: flex;
  gap: 8px;
  justify-content: space-between;
  min-width: 0;
}

.ops-monitor-vm-head strong {
  color: #0f172a;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-monitor-vm-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.ops-monitor-vm-meta span {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  padding: 4px 8px;
}

.ops-monitor-metrics {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.ops-monitor-metric {
  align-items: center;
  display: grid;
  gap: 8px;
  grid-template-columns: 36px minmax(46px, auto) minmax(0, 1fr);
  min-width: 0;
}

.ops-monitor-metric span,
.ops-monitor-metric strong {
  color: #0f172a;
  font-size: 12px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-monitor-metric i {
  background: #e8f0fa;
  border-radius: 999px;
  display: block;
  height: 8px;
  min-width: 0;
  overflow: hidden;
  width: 100%;
}

.ops-monitor-metric b {
  display: block;
  height: 100%;
}

.ops-monitor-metric b.is-ok {
  background: #22c55e;
}

.ops-monitor-metric b.is-warn {
  background: #f59e0b;
}

.ops-monitor-metric b.is-danger {
  background: #ef4444;
}

.ops-monitor-vm-foot {
  align-items: center;
  display: flex;
  gap: 8px;
  justify-content: flex-start;
  min-width: 0;
}

.ops-monitor-vm-foot > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-monitor-vm-foot > div {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
  min-width: 0;
}

.ops-monitor-detail,
.ops-monitor-cinder {
  background: #ffffff;
  border: 1px solid #d5e3f4;
  border-radius: 12px;
  box-shadow: 0 16px 32px rgba(15, 23, 42, 0.06);
}

.ops-monitor-detail {
  align-self: start;
  display: grid;
  gap: 12px;
  min-width: 0;
  padding: 16px;
  position: sticky;
  top: 16px;
}

.ops-monitor-detail h3,
.ops-monitor-cinder h3 {
  color: #0f172a;
  font-size: 18px;
  letter-spacing: 0;
  margin: 0;
}

.ops-monitor-detail-title {
  display: grid;
  gap: 8px;
}

.ops-monitor-detail-title strong {
  color: #0f172a;
  overflow-wrap: anywhere;
}

.ops-monitor-detail dl {
  display: grid;
  gap: 8px;
  margin: 0;
}

.ops-monitor-detail dl div {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  display: grid;
  gap: 4px;
  padding: 10px;
}

.ops-monitor-detail dt {
  color: #64748b;
  font-size: 12px;
  font-weight: 700;
}

.ops-monitor-detail dd {
  color: #0f172a;
  font-weight: 800;
  margin: 0;
  overflow-wrap: anywhere;
}

.ops-monitor-detail-actions,
.ops-monitor-cinder-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ops-monitor-cinder {
  align-items: center;
  display: grid;
  gap: 12px;
  grid-template-columns: minmax(0, 1fr) auto;
  padding: 18px;
}

.ops-monitor-cinder p {
  color: #475569;
  margin: 6px 0 0;
}

.ops-monitor-cinder-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

.ops-monitor-cinder-meta span {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  color: #334155;
  font-size: 12px;
  font-weight: 700;
  padding: 5px 9px;
}

.ops-monitor-cinder-result {
  grid-column: 1 / -1;
  margin: 0;
}

.ops-monitor-cinder-result span {
  display: block;
  margin-top: 4px;
}

.ops-monitor-empty {
  align-items: center;
  background: #ffffff;
  border: 1px dashed #cbd5e1;
  border-radius: 12px;
  color: #64748b;
  display: grid;
  gap: 6px;
  justify-items: center;
  min-height: 180px;
  padding: 24px;
}

.ops-monitor-empty strong {
  color: #0f172a;
}

@media (max-width: 920px) {
  .ops-monitor-hero,
  .ops-monitor-vm-foot {
    align-items: stretch;
    flex-direction: column;
