  .ops-monitor-toolbar {
    grid-template-columns: 1fr;
  }

  .ops-monitor-layout,
  .ops-monitor-cinder {
    grid-template-columns: 1fr;
  }

  .ops-monitor-detail {
    position: static;
  }
}

@media (max-width: 560px) {
  .ops-monitor-summary,
  .ops-monitor-grid {
    grid-template-columns: 1fr;
  }

  .ops-monitor-vm {
    grid-template-columns: 1fr;
  }
}

/* 2026 curriculum catalog */
.public-curriculum-shell {
  padding-top: 14px;
}

.public-curriculum-main {
  width: min(1280px, 100%);
  margin: 0 auto;
}

.public-curriculum-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
  padding: 10px 14px;
  border: 1px solid #dbe4ee;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.88);
  color: #64748b;
  font-size: 12px;
}

.public-curriculum-topbar a {
  color: #0f172a;
  font-weight: 800;
  text-decoration: none;
}

.curriculum-page {
  display: grid;
  gap: 18px;
  min-width: 0;
}

.curriculum-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  padding: 30px;
  overflow: hidden;
  border: 1px solid rgba(51, 65, 85, 0.12);
  border-radius: 20px;
  background:
    radial-gradient(circle at 90% 10%, rgba(14, 165, 233, 0.16), transparent 34%),
    linear-gradient(135deg, #ffffff 0%, #f6f8fb 100%);
  box-shadow: var(--shadow-sm);
}

.curriculum-hero h2 {
  margin: 4px 0 8px;
  color: #0f172a;
  font-size: clamp(26px, 3vw, 40px);
  line-height: 1.15;
  letter-spacing: -0.04em;
}

.curriculum-hero p:not(.card-label) {
  max-width: 720px;
  margin: 0;
  color: #475569;
  font-size: 15px;
}

.curriculum-hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 280px;
}

.curriculum-hero-actions > span {
  display: grid;
  min-width: 92px;
  padding: 10px 12px;
  border: 1px solid #dbe4ee;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.8);
  color: #64748b;
  font-size: 11px;
}

.curriculum-hero-actions > span strong {
  color: #0f172a;
  font-size: 20px;
  line-height: 1.1;
}

.curriculum-hero-actions .primary-btn {
  text-decoration: none;
}

.curriculum-toolbar {
  display: grid;
  grid-template-columns: minmax(230px, 0.8fr) minmax(0, 1.8fr);
  gap: 12px;
  padding: 14px;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #fff;
}

.curriculum-toolbar label {
  display: grid;
  gap: 5px;
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
}

.curriculum-toolbar input {
  width: 100%;
  min-height: 42px;
  padding: 0 13px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  background: #f8fafc;
  color: #0f172a;
  outline: none;
}

.curriculum-toolbar input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.14);
}

.curriculum-stage-tabs {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
  align-items: end;
}

.curriculum-stage-tabs button {
  min-height: 42px;
  padding: 7px 9px;
  border: 1px solid #dbe4ee;
  border-radius: 10px;
  background: #fff;
  color: #475569;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.curriculum-stage-tabs button:hover,
.curriculum-stage-tabs button:focus-visible {
  border-color: #93c5fd;
  background: #eff6ff;
  color: #1d4ed8;
}

.curriculum-stage-tabs button.is-active {
  border-color: #2563eb;
  background: #2563eb;
  color: #fff;
  box-shadow: 0 5px 12px rgba(37, 99, 235, 0.18);
}

.curriculum-layout {
  display: grid;
  grid-template-columns: minmax(210px, 260px) minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.curriculum-menu {
  position: sticky;
  top: 16px;
  max-height: calc(100vh - 32px);
  overflow: hidden;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #fff;
  box-shadow: var(--shadow-sm);
}

.curriculum-menu-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 14px 10px;
  border-bottom: 1px solid #edf1f5;
}

.curriculum-menu-head span {
  color: #64748b;
  font-size: 12px;
}

.curriculum-menu nav {
  display: grid;
  gap: 2px;
  max-height: calc(100vh - 92px);
  padding: 7px;
  overflow: auto;
}

.curriculum-menu button {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 7px;
  align-items: start;
  width: 100%;
  padding: 8px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #475569;
  text-align: left;
  cursor: pointer;
}

.curriculum-menu button > span {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  background: #eef2f7;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
}

.curriculum-menu button strong {
  overflow: hidden;
  font-size: 12px;
  line-height: 1.35;
  text-overflow: ellipsis;
}

.curriculum-menu button:hover,
.curriculum-menu button:focus-visible {
  background: #eff6ff;
  color: #1d4ed8;
}

.curriculum-menu button.is-active {
  background: #eaf3ff;
  color: #172554;
}

.curriculum-menu button.is-active > span {
  background: #2563eb;
  color: #fff;
}

.curriculum-course-list {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.curriculum-course-card {
  scroll-margin-top: 16px;
  overflow: hidden;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.035);
}

.curriculum-course-card.is-expanded {
  border-color: #a8c9f5;
  box-shadow: 0 18px 44px rgba(37, 99, 235, 0.09);
}

.curriculum-course-summary {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  gap: 13px;
  align-items: center;
  width: 100%;
  padding: 15px 16px;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.curriculum-course-summary:hover,
.curriculum-course-summary:focus-visible {
  background: #f8fafc;
}

.curriculum-course-number {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: #1e3a5f;
  color: #fff;
  font-size: 13px;
  font-weight: 900;
}

.curriculum-course-heading {
  display: grid;
  min-width: 0;
}

.curriculum-course-heading small {
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
}

.curriculum-course-heading strong {
  color: #0f172a;
  font-size: 16px;
  letter-spacing: -0.02em;
}

.curriculum-course-heading > span {
  overflow: hidden;
  color: #64748b;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.curriculum-course-meta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  max-width: 360px;
}

.curriculum-course-meta > span {
  padding: 5px 8px;
  border-radius: 999px;
  background: #eef2f7;
  color: #475569;
  font-size: 11px;
  font-weight: 700;
}

.curriculum-course-meta b {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  color: #2563eb;
  font-size: 20px;
}

.curriculum-course-body {
  display: grid;
  gap: 20px;
  padding: 22px;
  border-top: 1px solid #e2e8f0;
  background: linear-gradient(180deg, #fbfcfe 0%, #fff 160px);
}

.curriculum-course-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.curriculum-course-facts > div {
  display: grid;
  align-content: start;
  gap: 3px;
  min-height: 72px;
  padding: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #fff;
}

.curriculum-course-facts span {
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
}

.curriculum-course-facts strong {
  color: #1e293b;
  font-size: 12px;
}

.curriculum-copy-block,
.curriculum-list-block {
  min-width: 0;
}

.curriculum-copy-block h3,
.curriculum-list-block h3 {
  margin: 0 0 8px;
  color: #0f172a;
  font-size: 14px;
}

.curriculum-copy-block p {
  margin: 0 0 8px;
  color: #475569;
}

.curriculum-overview-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.curriculum-list-block {
  padding: 14px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #fff;
}

.curriculum-list-block ul {
  display: grid;
  gap: 5px;
  margin: 0;
  padding-left: 19px;
  color: #475569;
}

.curriculum-table-shell {
  min-width: 0;
  overflow-x: auto;
  border: 1px solid #dbe4ee;
  border-radius: 12px;
  background: #fff;
}

.curriculum-table {
  width: 100%;
  min-width: 680px;
  border-collapse: collapse;
}

.curriculum-table caption {
  padding: 13px 14px;
  border-bottom: 1px solid #e2e8f0;
  color: #0f172a;
  font-size: 14px;
  font-weight: 900;
  text-align: left;
}

.curriculum-table th,
.curriculum-table td {
  padding: 10px 12px;
  border-bottom: 1px solid #edf1f5;
  color: #475569;
  font-size: 12px;
  line-height: 1.45;
  text-align: left;
  vertical-align: top;
}

.curriculum-table th {
  background: #f1f5f9;
  color: #334155;
  font-size: 11px;
  white-space: nowrap;
}

.curriculum-table tr:last-child td {
  border-bottom: 0;
}

@media (max-width: 1080px) {
  .curriculum-toolbar {
    grid-template-columns: 1fr;
  }

  .curriculum-stage-tabs {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .curriculum-course-meta > span {
    display: none;
  }
}

@media (max-width: 820px) {
  .curriculum-hero {
    align-items: stretch;
    flex-direction: column;
    padding: 22px;
  }

  .curriculum-hero-actions {
    justify-content: flex-start;
    min-width: 0;
  }

  .curriculum-layout {
    grid-template-columns: 1fr;
  }

  .curriculum-menu {
    position: static;
    max-height: none;
  }

  .curriculum-menu nav {
    display: flex;
