    overflow-x: auto;
  }

  .curriculum-menu button {
    flex: 0 0 210px;
  }
}

@media (max-width: 620px) {
  .curriculum-stage-tabs {
    display: flex;
    overflow-x: auto;
  }

  .curriculum-stage-tabs button {
    flex: 0 0 auto;
  }

  .curriculum-course-summary {
    grid-template-columns: 40px minmax(0, 1fr) 30px;
    gap: 9px;
    padding: 13px;
  }

  .curriculum-course-number {
    width: 38px;
    height: 38px;
  }

  .curriculum-course-meta > b {
    width: 30px;
  }

  .curriculum-course-body {
    padding: 15px;
  }

  .curriculum-course-facts,
  .curriculum-overview-grid {
    grid-template-columns: 1fr;
  }
}

.curriculum-year-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin: 16px 0;
  padding: 14px 18px;
  border: 1px solid #cddff3;
  border-radius: 16px;
  background: linear-gradient(135deg, #f8fbff 0%, #edf5ff 100%);
  color: #1e3a5f;
  box-shadow: 0 10px 24px rgba(30, 64, 175, 0.06);
}

.curriculum-year-bar > div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.curriculum-year-bar button {
  min-width: 72px;
  padding: 8px 14px;
  border: 1px solid #c5d8ee;
  border-radius: 999px;
  color: #34506f;
  background: #ffffff;
  font-weight: 800;
  cursor: pointer;
}

.curriculum-year-bar button:hover,
.curriculum-year-bar button:focus-visible {
  border-color: #60a5fa;
  color: #1d4ed8;
  background: #eff6ff;
}

.curriculum-year-bar button.is-active {
  border-color: #2563eb;
  color: #ffffff;
  background: #2563eb;
  font-weight: 800;
  box-shadow: 0 6px 14px rgba(37, 99, 235, 0.22);
}

.admin-curriculum {
  display: grid;
  gap: 18px;
}

.admin-curriculum-header,
.admin-curriculum-upload,
.admin-curriculum-list {
  border: 1px solid #d9e5f2;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.05);
}

.admin-curriculum-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  padding: 22px;
}

.admin-curriculum-header h2,
.admin-curriculum-upload h3,
.admin-curriculum-list h3,
.admin-curriculum-year-info h4 {
  margin: 0;
}

.admin-curriculum-header p:last-child,
.admin-curriculum-upload-title p,
.admin-curriculum-submit-row p,
.admin-curriculum-year-info p {
  margin: 6px 0 0;
  color: #64748b;
}

.admin-curriculum-upload {
  padding: 22px;
}

.admin-curriculum-upload-title,
.admin-curriculum-submit-row,
.admin-curriculum-list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.admin-curriculum-replace-badge,
.admin-curriculum-year > span {
  display: inline-flex;
  align-items: center;
  width: max-content;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
}

.admin-curriculum-replace-badge {
  color: #92400e;
  background: #fef3c7;
}

.admin-curriculum-fields {
  display: grid;
  grid-template-columns: minmax(130px, 0.6fr) minmax(150px, 0.8fr) minmax(260px, 1.8fr);
  gap: 14px;
  margin-top: 18px;
}

.admin-curriculum-fields label:not(.admin-curriculum-publish-field) {
  display: grid;
  gap: 7px;
  color: #334155;
  font-size: 13px;
  font-weight: 700;
}

.admin-curriculum-fields input[type="number"],
.admin-curriculum-fields input[type="text"],
.admin-curriculum-fields input[type="file"] {
  width: 100%;
  min-height: 42px;
  padding: 9px 11px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  color: #0f172a;
  background: #f8fafc;
}

.admin-curriculum-publish-field {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 9px;
  color: #334155;
}

.admin-curriculum-submit-row {
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid #e2e8f0;
}

.admin-curriculum-status {
  padding: 12px 15px;
  border-radius: 12px;
}

.admin-curriculum-status.is-success {
  color: #166534;
  background: #dcfce7;
}

.admin-curriculum-status.is-error {
  color: #991b1b;
  background: #fee2e2;
}

.admin-curriculum-list {
  overflow: hidden;
}

.admin-curriculum-list-head {
  padding: 18px 20px;
  border-bottom: 1px solid #e2e8f0;
}

.admin-curriculum-list-head span {
  color: #94a3b8;
}

.admin-curriculum-year-card {
  display: grid;
  grid-template-columns: 110px minmax(240px, 1fr) auto;
  align-items: center;
  gap: 18px;
  padding: 18px 20px;
  border-bottom: 1px solid #edf2f7;
}

.admin-curriculum-year-card:last-child {
  border-bottom: 0;
}

.admin-curriculum-year {
  display: grid;
  gap: 7px;
}

.admin-curriculum-year > strong {
  font-size: 25px;
}

.admin-curriculum-year .is-published {
  color: #166534;
  background: #dcfce7;
}

.admin-curriculum-year .is-private {
  color: #475569;
  background: #e2e8f0;
}

.admin-curriculum-year-info small {
  display: block;
  margin-top: 6px;
  color: #64748b;
}

.admin-curriculum-year-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

@media (max-width: 820px) {
  .curriculum-year-bar,
  .admin-curriculum-header,
  .admin-curriculum-upload-title,
  .admin-curriculum-submit-row {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-curriculum-fields,
  .admin-curriculum-year-card {
    grid-template-columns: 1fr;
  }

  .admin-curriculum-year-actions {
    justify-content: flex-start;
  }
}

